package com.lastrites;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/** Parses observed server formats only. Unrecognised messages produce no notification. */
final class BroadcastParser
{
    private static final String VICTIM = "(.+?)\\s*\\((\\d{1,4}|\\d(?:\\.\\d+)?[kK])\\)";
    private static final Pattern KILLED = Pattern.compile(
        "^(.+?) killed " + VICTIM + " with an? (\\d+) damage hit(?: in (.+?))?[.!]?$");
    private static final Pattern DIED = Pattern.compile(
        "^" + VICTIM + " was killed by an? (\\d+) damage hit(?: from (.+?))?(?: in (.+?))?[.!]?$");

    private BroadcastParser() { }

    static Optional<DeathNotice> parse(String message, long id)
    {
        if (message == null || message.length() > 2048)
        {
            return Optional.empty();
        }
        // RuneLite's accessor removes game formatting. No player-chat messages enter here.
        String plain = Text.removeFormattingTags(Text.removeTags(message)).replace('\u00a0', ' ').trim();
        Matcher killed = KILLED.matcher(plain);
        Matcher died = DIED.matcher(plain);
        try
        {
            if (killed.matches())
            {
                return Optional.of(new DeathNotice(id, killed.group(2).trim(), killed.group(3),
                    killed.group(1).trim(), Integer.parseInt(killed.group(4)),
                    value(killed.group(5)), plain, null, false));
            }
            if (died.matches())
            {
                // A missing killer stays empty. Location alone cannot prove a cause of death.
                return Optional.of(new DeathNotice(id, died.group(1).trim(), died.group(2),
                    value(died.group(4)), Integer.parseInt(died.group(3)),
                    value(died.group(5)), plain, null, false));
            }
        }
        catch (NumberFormatException ignored)
        {
            // A changed/invalid server field must not break the client event thread.
        }
        return Optional.empty();
    }

    private static String value(String text) { return text == null ? "" : text.trim(); }
}

package com.lastrites;

/** Immutable facts from one broadcast; a HiScores total is a separately sourced value. */
public final class DeathNotice
{
    final long id;
    final String player;
    final String total;
    final String killer;
    final int damage;
    final String location;
    final String original;
    final Integer hiscoreTotal;
    final boolean preview;

    DeathNotice(long id, String player, String total, String killer, int damage,
        String location, String original, Integer hiscoreTotal, boolean preview)
    {
        this.id = id;
        this.player = player;
        this.total = total;
        this.killer = killer;
        this.damage = damage;
        this.location = location;
        this.original = original;
        this.hiscoreTotal = hiscoreTotal;
        this.preview = preview;
    }

    boolean hasAbbreviatedTotal()
    {
        return total.endsWith("K") || total.endsWith("k");
    }

    String totalLabel(boolean fullTotals)
    {
        return total + (fullTotals && hasAbbreviatedTotal() && hiscoreTotal != null ? " - " + hiscoreTotal : "");
    }

    String playerLabel(boolean fullTotals)
    {
        return player + " (" + total + ")"
            + (fullTotals && hasAbbreviatedTotal() && hiscoreTotal != null ? " - " + hiscoreTotal : "");
    }

    /** Stable filter fields avoid depending on the visual layout or English sentence order. */
    String filterText()
    {
        return "player=" + player + " total=" + (hiscoreTotal == null ? total : hiscoreTotal)
            + " broadcastTotal=" + total + " damage=" + damage + " killer=" + killer
            + " location=" + location;
    }

    DeathNotice withHiscoreTotal(int level)
    {
        return new DeathNotice(id, player, total, killer, damage, location, original, level, preview);
    }
}

package com.lastrites;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

/** User settings are persisted by RuneLite; overlay position uses OverlayManager. */
@ConfigGroup(LastRitesConfig.GROUP)
public interface LastRitesConfig extends Config
{
    String GROUP = "lastrites";

    @ConfigItem(keyName = "duration", name = "Display duration", description = "Seconds after a new death or sample. 0 keeps the pop-up visible until hidden.", position = 0)
    @Range(min = 0, max = 3600)
    default int duration() { return 7; }

    @ConfigItem(keyName = "popupEnabled", name = "Allow death pop-ups", description = "New deaths may display the pop-up. Manually hiding it turns this off; sample deaths still work.", position = 1)
    default boolean popupEnabled() { return true; }

    @ConfigItem(keyName = "lookupTotals", name = "Full totals from HiScores", description = "Look up abbreviated totals using RuneLite's Hardcore Main HiScores client. Enabled by default. HiScores may lag or reflect a reset.", position = 2)
    default boolean lookupTotals() { return true; }

    // Keep chat replacement independent of popup visibility and user exclusions.
    @ConfigItem(keyName = "hideDeathMessages", name = "Hide death messages in chat", description = "Replace recognised Hardcore Worlds death messages in chat with Last Rites pop-ups. Enabled by default. Popup visibility and death exclusions still apply.", position = 3)
    default boolean hideDeathMessages() { return true; }

    @ConfigItem(keyName = "excludeRegex", name = "Hide matching deaths", description = "One Java regex per line, case insensitive. Matches broadcast text and fields such as total=33. Example: \\btotal=33\\b. Invalid rules are shown in the sidebar.", position = 4)
    default String excludeRegex() { return ""; }
}

package com.lastrites;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseWheelEvent;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.input.MouseWheelListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Resizable achievement-style history viewport; RuneLite owns dragging and saved size/position. */
public final class LastRitesOverlay extends Overlay implements MouseWheelListener
{
    private static final Color GOLD = new Color(0xD5B371);
    private static final int SCROLL_UNIT = 16;
    private final NoticeQueue notices;
    private final LastRitesConfig config;
    private double scrollOffset;
    private int maximumScroll;
    private long lastRevision = -1;

    @Inject
    LastRitesOverlay(LastRitesPlugin plugin, NoticeQueue notices, LastRitesConfig config)
    {
        super(plugin);
        this.notices = notices;
        this.config = config;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
        // The same OverlayManager resize/position machinery used by IRL XP.
        // A custom-painted Overlay must apply preferredSize itself (OverlayPanel does so in super.render).
        setResizable(true);
        setMinimumSize(180);
    }

    @Override
    public synchronized Dimension render(Graphics2D graphics)
    {
        List<DeathNotice> rows = notices.visibleNotices();
        if (rows.isEmpty()) { return null; }
        if (lastRevision != notices.revision())
        {
            scrollOffset = 0;
            lastRevision = notices.revision();
        }
        Dimension preferred = getPreferredSize();
        int width = preferred == null ? 400 : Math.max(180, preferred.width);
        int height = preferred == null ? 200 : Math.max(180, preferred.height);
        float scale = Math.max(.7f, Math.min(1.8f, width / 400f));
        int header = Math.round(43 * scale);
        int footer = Math.round(23 * scale);
        int rowHeight = Math.round(105 * scale);
        int viewportHeight = height - header - footer;
        maximumScroll = Math.max(0, rows.size() * rowHeight - viewportHeight);
        scrollOffset = Math.max(0, Math.min(maximumScroll, scrollOffset));
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setPaint(new GradientPaint(0, 0, new Color(0x38262A), 0, height, new Color(0x14171D)));
            g.fillRoundRect(1, 1, width - 2, height - 2, 12, 12);
            g.setColor(GOLD);
            g.setStroke(new BasicStroke(1));
            g.drawRoundRect(4, 4, width - 9, height - 9, 9, 9);
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.round(11 * scale)));
            g.drawString(fit(g, "LAST RITES / HARDCORE FALLEN", width - 32), 16, Math.round(26 * scale));
            g.setColor(new Color(0x775B48));
            g.drawLine(12, header - 1, width - 13, header - 1);
            Graphics2D body = (Graphics2D) g.create();
            try
            {
                body.clipRect(10, header, width - 23, viewportHeight);
                for (int i = 0; i < rows.size(); i++)
                {
                    int y = header + i * rowHeight - (int) scrollOffset;
                    if (y + rowHeight < header || y > height - footer) { continue; }
                    drawDeath(body, rows.get(i), y, width, rowHeight, scale);
                }
            }
            finally { body.dispose(); }
            g.setColor(new Color(0xA49A91));
            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, Math.round(10 * scale)));
            String hint = rows.size() > 1 ? "Scroll to browse recent deaths" : rows.get(0).preview ? "Sample death" : "Latest death";
            g.drawString(fit(g, hint, width - 32), 16, height - Math.round(9 * scale));
            if (maximumScroll > 0)
            {
                int thumbHeight = Math.max(12, viewportHeight * viewportHeight / (rows.size() * rowHeight));
                int thumbY = header + (int) ((viewportHeight - thumbHeight) * scrollOffset / maximumScroll);
                g.setColor(GOLD);
                g.fillRoundRect(width - 12, thumbY, 3, thumbHeight, 3, 3);
            }
        }
        finally { g.dispose(); }
        return new Dimension(width, height);
    }

    private void drawDeath(Graphics2D g, DeathNotice notice, int y, int width, int rowHeight, float scale)
    {
        g.setFont(new Font(Font.SERIF, Font.BOLD, Math.round(21 * scale)));
        g.setColor(new Color(0xFFF1D4));
        g.drawString(fit(g, notice.playerLabel(config.lookupTotals()), width - 37), 16, y + Math.round(28 * scale));
        g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, Math.round(13 * scale)));
        g.setColor(new Color(0xE7DDCF));
        String cause = notice.killer.isEmpty() ? "" : "Slain by " + notice.killer + "  ·  ";
        g.drawString(fit(g, cause + notice.damage + " damage", width - 37), 16, y + Math.round(53 * scale));
        g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, Math.round(12 * scale)));
        g.setColor(new Color(0xA49A91));
        String location = notice.preview ? "PREVIEW" + (notice.location.isEmpty() ? "" : " · " + notice.location) : notice.location;
        if (!location.isEmpty()) { g.drawString(fit(g, location, width - 37), 16, y + Math.round(76 * scale)); }
        g.setColor(new Color(0x59443A));
        g.drawLine(16, y + rowHeight - 5, width - 20, y + rowHeight - 5);
    }

    @Override
    public synchronized MouseWheelEvent mouseWheelMoved(MouseWheelEvent event)
    {
        // MouseManager supplies canvas coordinates after stretched-mode translation.
        // Consume only over this visible overlay so world-camera scrolling still works elsewhere.
        Rectangle bounds = new Rectangle(getBounds());
        if (!event.isConsumed() && notices.isVisible() && bounds.contains(event.getPoint()))
        {
            double units = event.getScrollType() == MouseWheelEvent.WHEEL_BLOCK_SCROLL
                ? Math.max(1, bounds.height - 60) : SCROLL_UNIT * Math.max(1, event.getScrollAmount());
            scrollOffset = Math.max(0, Math.min(maximumScroll,
                scrollOffset + event.getPreciseWheelRotation() * units));
            event.consume();
        }
        return event;
    }

    private static String fit(Graphics2D g, String text, int width)
    {
        FontMetrics metrics = g.getFontMetrics();
        if (metrics.stringWidth(text) <= width) { return text; }
        int end = text.length();
        while (end > 0 && metrics.stringWidth(text.substring(0, end) + "…") > width) { end--; }
        return text.substring(0, end) + "…";
    }
}

package com.lastrites;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.Timer;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.PluginPanel;

/** Preview, local exclusions, history, and Plugin Hub support guidance share the sidebar. */
final class LastRitesPanel extends PluginPanel
{
    private final Timer timer;
    private final JTextArea recent = note("", 14);
    private final JTextArea errors = note("", 3);
    private final JTextArea filters = new JTextArea(5, 18);

    LastRitesPanel(NoticeQueue notices, LastRitesConfig config, ConfigManager manager,
        Runnable togglePopup)
    {
        setLayout(new BorderLayout(0, 12));
        setBorder(BorderFactory.createEmptyBorder(14, 10, 14, 10));
        JPanel controls = new JPanel();
        controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS));
        JLabel title = new JLabel("LAST RITES");
        title.setForeground(new Color(0xD5B371));
        title.setFont(title.getFont().deriveFont(java.awt.Font.BOLD, 18f));
        controls.add(title);
        controls.add(Box.createVerticalStrut(12));
        controls.add(note("Move: Windows Alt + drag; Mac Option + drag. Hold the same key and drag an edge to resize. RuneLite saves the size and position.", 6));
        JLabel visibility = new JLabel();
        visibility.setName("popupVisibility");
        controls.add(visibility);
        JCheckBox automatic = new JCheckBox("Show on new deaths", config.popupEnabled());
        automatic.setName("popupAutomatic");
        automatic.setOpaque(false);
        automatic.setToolTipText("Uncheck to keep the pop-up hidden on new deaths. Sample deaths still work.");
        automatic.addActionListener(event -> {
            manager.setConfiguration(LastRitesConfig.GROUP, "popupEnabled", automatic.isSelected());
            notices.configure(config.duration(), automatic.isSelected());
        });
        controls.add(automatic);
        JButton position = button("Show pop-up");
        position.setName("popupToggle");
        position.addActionListener(event -> togglePopup.run());
        controls.add(position);
        JButton preview = button("Show sample death");
        preview.setName("popupSample");
        preview.addActionListener(event -> notices.showSample());
        controls.add(preview);
        controls.add(Box.createVerticalStrut(8));
        controls.add(new JLabel("Display duration (seconds)"));
        JSpinner duration = new JSpinner(new SpinnerNumberModel(Math.max(0, Math.min(3600, config.duration())), 0, 3600, 1));
        duration.setName("popupDuration");
        duration.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        duration.addChangeListener(event -> manager.setConfiguration(LastRitesConfig.GROUP,
            "duration", ((Number) duration.getValue()).intValue()));
        controls.add(duration);
        controls.add(note("0 seconds keeps the pop-up visible. Default: 7 seconds. Manually showing it keeps it open until hidden.", 5));
        JCheckBox fullTotals = new JCheckBox("Full totals (network lookup)", config.lookupTotals());
        fullTotals.setName("popupFullTotals");
        fullTotals.setOpaque(false);
        fullTotals.setToolTipText("Optional network requests send broadcast player names to Jagex HiScores. Off by default.");
        fullTotals.addActionListener(event -> manager.setConfiguration(LastRitesConfig.GROUP,
            "lookupTotals", fullTotals.isSelected()));
        controls.add(fullTotals);
        controls.add(note("Optional: sends broadcast player names to Jagex HiScores to fetch full totals.", 3));
        controls.add(Box.createVerticalStrut(12));
        controls.add(note("Hide matching deaths — one regex per line. Example: \\btotal=33\\b\nMatches the broadcast and named fields.", 5));
        filters.setText(config.excludeRegex());
        filters.setLineWrap(true);
        JScrollPane filterScroll = new JScrollPane(filters);
        filterScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 110));
        filterScroll.getVerticalScrollBar().setUnitIncrement(16);
        handOffWheelAtEdges(filterScroll);
        controls.add(filterScroll);
        JButton apply = button("Save filters");
        apply.addActionListener(event -> manager.setConfiguration(LastRitesConfig.GROUP,
            "excludeRegex", filters.getText()));
        controls.add(apply);
        errors.setForeground(new Color(0xD8877C));
        controls.add(errors);
        controls.add(note("Filters use Java regex syntax. Valid rules still work when another rule has an error.", 5));
        controls.add(note("Full totals appear after the broadcast total, for example (1K) - 1075. HiScores may lag or reflect a reset.", 5));
        controls.add(new JLabel("Recent deaths (this session)"));
        JScrollPane recentScroll = new JScrollPane(recent);
        recentScroll.setPreferredSize(new Dimension(200, 260));
        recentScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 260));
        recentScroll.getVerticalScrollBar().setUnitIncrement(16);
        handOffWheelAtEdges(recentScroll);
        controls.add(recentScroll);
        JTextArea support = note("To report a bug, open this plugin's Plugin Hub page and use \"Report an issue\".", 4);
        support.setName("supportInstructions");
        controls.add(support);
        // PluginPanel's parent supplies scrolling; all long text wraps to sidebar width.
        add(controls, BorderLayout.NORTH);
        getScrollPane().getVerticalScrollBar().setUnitIncrement(16);
        timer = new Timer(150, event ->
        {
            boolean shown = notices.isVisible();
            visibility.setText(shown ? "Pop-up: visible" : "Pop-up: hidden");
            visibility.setForeground(shown ? new Color(0x82C58D) : new Color(0xC9AD7A));
            position.setText(shown ? "Hide pop-up" : "Show pop-up");
            automatic.setSelected(config.popupEnabled());
            fullTotals.setSelected(config.lookupTotals());
            if (!duration.hasFocus() && !((JSpinner.DefaultEditor) duration.getEditor()).getTextField().hasFocus()
                && ((Number) duration.getValue()).intValue() != config.duration())
            {
                duration.setValue(config.duration());
            }
            errors.setText(notices.filterErrors());
            StringBuilder text = new StringBuilder();
            for (DeathNotice notice : notices.history())
            {
                text.append(notice.playerLabel(config.lookupTotals())).append("\n");
                if (!notice.killer.isEmpty()) { text.append(notice.killer).append(" · "); }
                text.append(notice.damage).append(" damage\n");
                if (!notice.location.isEmpty()) { text.append(notice.location).append("\n"); }
                text.append("\n");
            }
            String next = text.length() == 0 ? "No deaths received yet." : text.toString();
            if (!next.equals(recent.getText())) { recent.setText(next); }
        });
        timer.start();
    }

    void stop() { timer.stop(); }

    /** Match IRL XP: nested panes pass wheel input to the sidebar at their edges. */
    private static void handOffWheelAtEdges(JScrollPane pane)
    {
        pane.addMouseWheelListener(event -> {
            double rotation = event.getPreciseWheelRotation();
            javax.swing.JScrollBar bar = pane.getVerticalScrollBar();
            boolean canScroll = bar.isVisible() && (rotation < 0 ? bar.getValue() > bar.getMinimum()
                : bar.getValue() + bar.getVisibleAmount() < bar.getMaximum());
            if (rotation != 0 && !canScroll && pane.getParent() != null)
            {
                pane.getParent().dispatchEvent(javax.swing.SwingUtilities.convertMouseEvent(pane, event, pane.getParent()));
            }
        });
    }

    private static JButton button(String text)
    {
        JButton button = new JButton(text);
        button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
        button.setAlignmentX(LEFT_ALIGNMENT);
        return button;
    }

    private static JTextArea note(String text, int rows)
    {
        JTextArea area = new JTextArea(text);
        area.setFont(new JLabel().getFont());
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        area.setEditable(false);
        area.setOpaque(false);
        area.setRows(rows);
        area.setAlignmentX(LEFT_ALIGNMENT);
        return area;
    }
}

package com.lastrites;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.TimeUnit;
import java.time.temporal.ChronoUnit;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.WorldType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.hiscore.HiscoreClient;
import net.runelite.client.hiscore.HiscoreEndpoint;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.Skill;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

/** Translates trusted Hardcore broadcasts into local presentation and optional HiScores enrichment. */
@PluginDescriptor(name = "Last Rites", description = "Movable Hardcore Worlds death announcements",
    tags = {"hardcore", "death", "broadcast", "notification"})
public class LastRitesPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private LastRitesConfig config;
    @Inject private ConfigManager configManager;
    @Inject private OverlayManager overlays;
    @Inject private LastRitesOverlay overlay;
    @Inject private NoticeQueue notices;
    @Inject private ClientToolbar toolbar;
    @Inject private HiscoreClient hiscores;
    @Inject private MouseManager mouseManager;
    private final Deque<DeathNotice> lookups = new ArrayDeque<>();
    private NavigationButton navigation;
    private LastRitesPanel panel;
    private long nextId;
    private volatile long lifecycle;
    private volatile boolean running;
    private volatile boolean lookupInProgress;

    @Provides LastRitesConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(LastRitesConfig.class);
    }

    @Override
    protected void startUp() throws Exception
    {
        lifecycle++;
        running = true;
        clientThread.invoke(client::refreshChat);
        notices.configure(config.duration(), config.popupEnabled());
        notices.setFilters(config.excludeRegex());
        overlays.add(overlay);
        mouseManager.registerMouseWheelListener(overlay);
        onEdt(() ->
        {
            panel = new LastRitesPanel(notices, config, configManager, this::togglePopup);
            navigation = NavigationButton.builder().tooltip("Last Rites").priority(8)
                .icon(icon()).panel(panel).build();
            toolbar.addNavigation(navigation);
        });
    }

    @Override
    protected void shutDown() throws Exception
    {
        running = false;
        // Rebuild buffered chat without our filter when the plugin is disabled.
        clientThread.invoke(client::refreshChat);
        lifecycle++;
        synchronized (lookups) { lookups.clear(); }
        mouseManager.unregisterMouseWheelListener(overlay);
        overlays.remove(overlay);
        notices.clear();
        onEdt(() ->
        {
            if (navigation != null) { toolbar.removeNavigation(navigation); }
            if (panel != null) { panel.stop(); }
            navigation = null;
            panel = null;
        });
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        // Only server channels on the API's explicit Hardcore world flag qualify.
        // ChatMessage.name/sender/timestamp/messageNode carry no additional death facts.
        if (!acceptsDeathMessages(event.getType()))
        {
            return;
        }
        BroadcastParser.parse(event.getMessage(), ++nextId).ifPresent(notice ->
        {
            if (notices.add(notice) && notice.hasAbbreviatedTotal() && config.lookupTotals())
            {
                synchronized (lookups)
                {
                    if (lookups.size() >= 25) { lookups.removeFirst(); }
                    lookups.addLast(notice);
                }
            }
        });
    }

    @Subscribe
    public void onScriptCallbackEvent(ScriptCallbackEvent event)
    {
        if (!running || !config.hideDeathMessages() || !"chatFilterCheck".equals(event.getEventName()))
        {
            return;
        }
        // RuneLite's ChatFilterPlugin contract: the top three ints are the
        // visibility flag, ChatMessageType id, and MessageNode id, respectively.
        // Only set visibility to zero; never undo another plugin's decision.
        int[] stack = client.getIntStack();
        int size = client.getIntStackSize();
        if (size < 3 || !acceptsDeathMessages(ChatMessageType.of(stack[size - 2])))
        {
            return;
        }
        MessageNode message = client.getMessages().get(stack[size - 1]);
        // Use the original node value, not the display string another plugin
        // may have censored. Name, sender, timestamp, and format are not death data.
        // Reuse the verified broadcast parser without adding to history or lookups:
        // this callback runs again when chat is rebuilt, not just on new messages.
        if (message != null && BroadcastParser.parse(message.getValue(), 0).isPresent())
        {
            stack[size - 3] = 0;
        }
    }

    private boolean acceptsDeathMessages(ChatMessageType type)
    {
        // Both ingestion and chat replacement use the same world/channel boundary.
        return running && client.getWorldType().contains(WorldType.HARDCORE_MAIN)
            && (type == ChatMessageType.BROADCAST || type == ChatMessageType.GAMEMESSAGE);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (LastRitesConfig.GROUP.equals(event.getGroup()))
        {
            notices.configure(config.duration(), config.popupEnabled());
            notices.setFilters(config.excludeRegex());
            if (!config.lookupTotals()) { synchronized (lookups) { lookups.clear(); } }
            if ("hideDeathMessages".equals(event.getKey()))
            {
                // Config events can originate on Swing's EDT; chat belongs to the client thread.
                clientThread.invoke(client::refreshChat);
            }
        }
    }

    private void togglePopup()
    {
        if (notices.isVisible())
        {
            configManager.setConfiguration(LastRitesConfig.GROUP, "popupEnabled", false);
            notices.hide();
        }
        else
        {
            configManager.setConfiguration(LastRitesConfig.GROUP, "popupEnabled", true);
            notices.showPinned();
        }
    }

    @Schedule(period = 1, unit = ChronoUnit.SECONDS, asynchronous = true)
    public void resolveNextTotal()
    {
        if (!running || !config.lookupTotals() || lookupInProgress) { return; }
        final DeathNotice notice;
        synchronized (lookups) { notice = lookups.pollFirst(); }
        if (notice == null) { return; }
        long generation = lifecycle;
        lookupInProgress = true;
        // One pending result at a time and at most one start per second. RuneLite's
        // API does not expose the HTTP Call; timeout ends waiting, not necessarily I/O.
        // No normal/ironman fallback:
        // a different table can describe a different incarnation of this character.
        hiscores.lookupAsync(notice.player, HiscoreEndpoint.HARDCORE_MAIN)
            .orTimeout(8, TimeUnit.SECONDS).whenComplete((result, error) ->
            {
                try
                {
                    if (running && lifecycle == generation && config.lookupTotals() && error == null && result != null)
                    {
                        // getSkill may return null. Only OVERALL.level is used; player,
                        // rank, XP, all other skills, and activities are intentionally ignored.
                        Skill overall = result.getSkill(HiscoreSkill.OVERALL);
                        if (overall != null && overall.getLevel() > 0)
                        {
                            notices.enrich(notice.id, overall.getLevel());
                        }
                    }
                }
                finally { lookupInProgress = false; }
            });
    }

    private static BufferedImage icon()
    {
        BufferedImage image = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setColor(new Color(0xD5B371));
        g.fillOval(3, 2, 18, 17);
        g.fillRect(7, 15, 10, 7);
        g.setColor(new Color(0x211B20));
        g.fillOval(6, 8, 5, 5);
        g.fillOval(14, 8, 5, 5);
        g.dispose();
        return image;
    }

    private static void onEdt(Runnable action) throws Exception
    {
        // Plugin toggles may already run on the EDT; invokeAndWait cannot be nested.
        if (SwingUtilities.isEventDispatchThread()) { action.run(); }
        else { SwingUtilities.invokeAndWait(action); }
    }
}

package com.lastrites;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

/** Compiled user regex exclusions using the JDK's standard Pattern API. */
final class NoticeFilters
{
    private final List<Pattern> patterns = new ArrayList<>();
    private final List<String> errors = new ArrayList<>();

    NoticeFilters(String text)
    {
        String[] lines = text.split("\\R", -1);
        for (int i = 0; i < lines.length; i++)
        {
            if (i >= 32)
            {
                errors.add("Only the first 32 filter lines are used.");
                break;
            }
            if (lines[i].isBlank()) { continue; }
            if (lines[i].length() > 512)
            {
                errors.add("Filter line " + (i + 1) + " exceeds the limit (32 rules, 512 characters each).");
                continue;
            }
            try
            {
                patterns.add(Pattern.compile(lines[i], Pattern.CASE_INSENSITIVE));
            }
            catch (PatternSyntaxException ex)
            {
                errors.add("Filter line " + (i + 1) + ": " + ex.getDescription());
            }
        }
    }

    boolean excludes(DeathNotice notice)
    {
        for (Pattern pattern : patterns)
        {
            if (pattern.matcher(notice.original).find() || pattern.matcher(notice.filterText()).find())
            {
                return true;
            }
        }
        return false;
    }

    String errorText() { return String.join("\n", errors); }
}

package com.lastrites;

import java.time.Clock;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Session history and popup lifecycle, shared safely by event, render, HTTP, and Swing threads. */
@Singleton
final class NoticeQueue
{
    private final Clock clock;
    private final Deque<DeathNotice> history = new ArrayDeque<>();
    private NoticeFilters filters = new NoticeFilters("");
    private DeathNotice preview;
    private boolean automaticEnabled = true;
    private boolean visible;
    private boolean pinned;
    private int duration = 7;
    private long triggeredAt;
    private long revision;

    @Inject NoticeQueue() { this(Clock.systemUTC()); }
    NoticeQueue(Clock clock) { this.clock = clock; }

    synchronized void configure(int seconds, boolean enabled)
    {
        duration = Math.max(0, Math.min(3600, seconds));
        if (automaticEnabled && !enabled) { hide(); }
        automaticEnabled = enabled;
        expire();
    }

    synchronized void setFilters(String text)
    {
        filters = new NoticeFilters(text);
        history.removeIf(filters::excludes);
        if (preview == null && history.isEmpty() && !pinned) { visible = false; }
        revision++;
    }

    synchronized String filterErrors() { return filters.errorText(); }

    synchronized boolean add(DeathNotice notice)
    {
        if (notice.preview) { showSample(); return true; }
        if (filters.excludes(notice)) { return false; }
        history.addFirst(notice);
        while (history.size() > 50) { history.removeLast(); }
        revision++;
        if (automaticEnabled)
        {
            // Every new death restarts the timed view; a manual Show remains pinned.
            preview = null;
            visible = true;
            triggeredAt = clock.millis();
        }
        return true;
    }

    synchronized void showSample()
    {
        // A sample overrides manual hiding without changing the saved automatic preference.
        preview = sample();
        pinned = false;
        visible = true;
        triggeredAt = clock.millis();
        revision++;
    }

    synchronized void showPinned()
    {
        automaticEnabled = true;
        preview = history.isEmpty() ? sample() : null;
        pinned = true;
        visible = true;
        revision++;
    }

    synchronized void hide()
    {
        automaticEnabled = false;
        visible = false;
        pinned = false;
        preview = null;
        revision++;
    }

    synchronized boolean isVisible() { expire(); return visible; }
    synchronized long revision() { return revision; }

    synchronized List<DeathNotice> visibleNotices()
    {
        expire();
        List<DeathNotice> result = new ArrayList<>();
        if (!visible) { return result; }
        if (preview != null) { result.add(preview); }
        result.addAll(history);
        return result;
    }

    synchronized DeathNotice current()
    {
        List<DeathNotice> rows = visibleNotices();
        return rows.isEmpty() ? null : rows.get(0);
    }

    synchronized void enrich(long id, int total)
    {
        if (total <= 0) { return; }
        List<DeathNotice> records = new ArrayList<>();
        for (DeathNotice notice : history)
        {
            DeathNotice next = notice.id == id ? notice.withHiscoreTotal(total) : notice;
            if (!filters.excludes(next)) { records.add(next); }
        }
        history.clear();
        history.addAll(records);
        if (history.isEmpty() && preview == null && !pinned) { visible = false; }
    }

    synchronized List<DeathNotice> history() { return new ArrayList<>(history); }

    synchronized void clear()
    {
        history.clear();
        preview = null;
        visible = false;
        pinned = false;
        revision++;
    }

    private void expire()
    {
        // Zero is deliberately persistent; only timed automatic/sample displays expire.
        if (visible && !pinned && duration > 0 && clock.millis() - triggeredAt >= duration * 1000L)
        {
            visible = false;
            preview = null;
        }
    }

    static DeathNotice sample()
    {
        return new DeathNotice(-1, "Fallen Adventurer", "1.1K", "Hill Giant", 12,
            "Asgarnia", "Preview only", 1142, true);
    }
}

package com.lastrites;

import java.awt.Dimension;
