            String death = "Damis killed X(33) with a 2 damage hit.";
            for (ChatMessageType type : ChatMessageType.values())
            {
                if (type == ChatMessageType.BROADCAST || type == ChatMessageType.GAMEMESSAGE) { continue; }
                int[] stack = f.chatStack(type, death, 1);
                f.filterChat();
                assertEquals(1, stack[1], type.toString());
            }
            int[] unrelated = f.chatStack(ChatMessageType.BROADCAST, "A server announcement.", 1);
            f.filterChat();
            assertEquals(1, unrelated[1]);
            int[] otherWorld = f.chatStack(ChatMessageType.BROADCAST, death, 1);
            when(f.client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
            f.filterChat();
            assertEquals(1, otherWorld[1]);
            when(f.client.getWorldType()).thenReturn(EnumSet.of(WorldType.HARDCORE_MAIN));
            net.runelite.api.events.ScriptCallbackEvent other = new net.runelite.api.events.ScriptCallbackEvent();
            other.setEventName("unrelatedCallback");
            f.plugin.onScriptCallbackEvent(other);
            assertEquals(1, otherWorld[1]);
            int[] blocked = f.chatStack(ChatMessageType.GAMEMESSAGE, "An already hidden message.", 0);
            f.filterChat();
            assertEquals(0, blocked[1]);
            assertTrue(f.queue.history().isEmpty());
            verifyNoInteractions(f.hiscores);
        }
        finally { f.stop(); }
    }

    @Test
    void chatReplacementDoesNotDependOnPopupVisibilityOrExclusions() throws Exception
    {
        Fixture f = new Fixture();
        when(f.config.popupEnabled()).thenReturn(false);
        when(f.config.excludeRegex()).thenReturn("total=33");
        f.plugin.startUp();
        try
        {
            for (String total : new String[] {"33", "34"})
            {
                String death = "Damis killed X(" + total + ") with a 2 damage hit.";
                f.plugin.onChatMessage(message(ChatMessageType.BROADCAST, death));
                int[] stack = f.chatStack(ChatMessageType.BROADCAST, death, 1);
                f.filterChat();
                assertEquals(0, stack[1]);
            }
            assertFalse(f.queue.isVisible());
            assertEquals(1, f.queue.history().size());
            assertEquals("34", f.queue.history().get(0).total);
        }
        finally { f.stop(); }
    }

    @Test
    void refreshesBufferedChatOnToggleAndLifecycleWithoutDestroyingMessages() throws Exception
    {
        Fixture f = new Fixture();
        f.plugin.startUp();
        try
        {
            verify(f.client).refreshChat();
            when(f.config.hideDeathMessages()).thenReturn(false);
            net.runelite.client.events.ConfigChanged changed = new net.runelite.client.events.ConfigChanged();
            changed.setGroup(LastRitesConfig.GROUP);
            changed.setKey("hideDeathMessages");
            f.plugin.onConfigChanged(changed);
            int[] visible = f.chatStack(ChatMessageType.BROADCAST, "Damis killed X(33) with a 2 damage hit.", 1);
            f.filterChat();
            assertEquals(1, visible[1]);
            when(f.config.hideDeathMessages()).thenReturn(true);
            f.plugin.onConfigChanged(changed);
            f.filterChat();
            assertEquals(0, visible[1]);
            verify(f.client, times(3)).refreshChat();
        }
        finally { f.stop(); }
        verify(f.client, times(4)).refreshChat();
        int[] stopped = f.chatStack(ChatMessageType.BROADCAST, "Damis killed X(33) with a 2 damage hit.", 1);
        f.filterChat();
        assertEquals(1, stopped[1]);
        // Starting the same plugin again must restore filtering without cached message ids.
        f.plugin.startUp();
        try
        {
            f.filterChat();
            assertEquals(0, stopped[1]);
            verify(f.client, times(5)).refreshChat();
        }
        finally { f.stop(); }
    }

    @Test
    void ignoresMissingMessageNodesAndIncompleteCallbackStacks() throws Exception
    {
        Fixture f = new Fixture();
        f.plugin.startUp();
        try
        {
            int[] stack = f.chatStack(ChatMessageType.BROADCAST, null, 1);
            f.filterChat();
            assertEquals(1, stack[1]);
            when(f.messages.get(42)).thenReturn(null);
            f.filterChat();
            assertEquals(1, stack[1]);
            when(f.client.getIntStackSize()).thenReturn(2);
            f.filterChat();
            assertEquals(1, stack[1]);
        }
        finally { f.stop(); }
    }

    private static ChatMessage message(ChatMessageType type, String text)
    {
        return new ChatMessage(null, type, "", text, "", 0);
    }

    private static void inject(Object owner, String name, Object value) throws Exception
    {
        Field field = owner.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(owner, value);
    }

    private static final class Fixture
    {
        final LastRitesPlugin plugin = new LastRitesPlugin();
        final Client client = mock(Client.class);
        // Exercise real default settings unless a test explicitly overrides one.
        final LastRitesConfig config = mock(LastRitesConfig.class, CALLS_REAL_METHODS);
        final HiscoreClient hiscores = mock(HiscoreClient.class);
        final NoticeQueue queue = new NoticeQueue();
        final net.runelite.api.MessageNode node = mock(net.runelite.api.MessageNode.class);
        // Java erases the table's type argument when Mockito creates this mock.
        @SuppressWarnings("unchecked")
        final net.runelite.api.IterableHashTable<net.runelite.api.MessageNode> messages = mock(net.runelite.api.IterableHashTable.class);

        Fixture() throws Exception
        {
            when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.HARDCORE_MAIN));
            net.runelite.client.callback.ClientThread clientThread = mock(net.runelite.client.callback.ClientThread.class);
            // Execute scheduled refreshes deterministically without a running game loop.
            doAnswer(call -> { ((Runnable) call.getArgument(0)).run(); return null; })
                .when(clientThread).invoke(any(Runnable.class));
            inject(plugin, "client", client);
            inject(plugin, "clientThread", clientThread);
            inject(plugin, "config", config);
            inject(plugin, "configManager", mock(ConfigManager.class));
            inject(plugin, "overlays", mock(OverlayManager.class));
            inject(plugin, "overlay", new LastRitesOverlay(plugin, queue, config));
            inject(plugin, "notices", queue);
            inject(plugin, "toolbar", mock(ClientToolbar.class));
            inject(plugin, "hiscores", hiscores);
            inject(plugin, "mouseManager", mock(net.runelite.client.input.MouseManager.class));
        }

        int[] chatStack(ChatMessageType type, String text, int visible)
        {
            // Include a prefix to verify offsets are relative to stack size.
            int[] stack = {87, visible, type.getType(), 42};
            when(client.getIntStack()).thenReturn(stack);
            when(client.getIntStackSize()).thenReturn(stack.length);
            when(client.getMessages()).thenReturn(messages);
            when(messages.get(42)).thenReturn(node);
            when(node.getValue()).thenReturn(text);
            return stack;
        }

        void filterChat()
        {
            net.runelite.api.events.ScriptCallbackEvent callback = new net.runelite.api.events.ScriptCallbackEvent();
            callback.setEventName("chatFilterCheck");
            plugin.onScriptCallbackEvent(callback);
        }

        void stop() throws Exception
        {
            SwingUtilities.invokeAndWait(() ->
            {
                try { plugin.shutDown(); }
                catch (Exception ex) { throw new RuntimeException(ex); }
            });
        }
    }
}

package com.lastrites;

import java.awt.Canvas;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.Arrays;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Exercises the user's manual-hide, sample override, timer, and history browsing contracts. */
class PopupLifecycleTest
{
    @Test
    void timerExpiryAllowsNextDeathButManualHidingBlocksIt()
    {
        MutableClock clock = new MutableClock();
        NoticeQueue state = new NoticeQueue(clock);
        state.configure(7, true);
        state.add(death(1));
        assertTrue(state.isVisible());
        clock.now = 7000;
        assertFalse(state.isVisible());
        state.add(death(2));
        assertTrue(state.isVisible());
        state.hide();
        state.add(death(3));
        assertFalse(state.isVisible());
        assertEquals(3, state.history().size());
    }

    @Test
    void sampleOverridesHidingWithoutEnablingAutomaticDeathsAndZeroNeverExpires()
    {
        MutableClock clock = new MutableClock();
        NoticeQueue state = new NoticeQueue(clock);
        state.configure(2, false);
        state.showSample();
        assertTrue(state.isVisible());
        clock.now = 1000;
        state.add(death(1));
        clock.now = 2000;
        assertFalse(state.isVisible());
        state.add(death(2));
        assertFalse(state.isVisible());
        state.configure(0, false);
        state.showSample();
        clock.now = 86400000;
        assertTrue(state.isVisible());
        state.hide();
        assertFalse(state.isVisible());
        state.configure(2, false);
        state.showPinned();
        clock.now += 86400000;
        state.add(death(3));
        clock.now += 86400000;
        assertTrue(state.isVisible());
    }

    @Test
    void eachNewDeathRestartsTimerAndChangingDurationAppliesToCurrentDisplay()
    {
        MutableClock clock = new MutableClock();
        NoticeQueue state = new NoticeQueue(clock);
        state.configure(7, true);
        state.add(death(1));
        clock.now = 6000;
        state.add(death(2));
        clock.now = 12000;
        assertTrue(state.isVisible());
        state.configure(0, true);
        clock.now = 999999;
        assertTrue(state.isVisible());
        state.configure(2, true);
        assertFalse(state.isVisible());
    }

    @Test
    void broadcastAndFullTotalsStayCompactAndToggleIndependently()
    {
        DeathNotice notice = new DeathNotice(1, "Example", "1K", "", 4, "", "", 1075, false);
        assertEquals("Example (1K) - 1075", notice.playerLabel(true));
        assertEquals("Example (1K)", notice.playerLabel(false));
        assertEquals("1K", notice.totalLabel(false));
    }

    @Test
    void wheelScrollsOnlyVisiblePopupAndResizedViewportHonoursSavedSize()
    {
        NoticeQueue state = new NoticeQueue();
        state.configure(0, true);
        for (int i = 0; i < 60; i++) { state.add(death(i)); }
        assertEquals(50, state.history().size());
        LastRitesConfig settings = mock(LastRitesConfig.class);
        LastRitesOverlay overlay = new LastRitesOverlay(null, state, settings);
        overlay.setPreferredSize(new Dimension(280, 360));
        BufferedImage before = render(overlay);
        overlay.getBounds().setBounds(10, 10, 280, 360);
        MouseWheelEvent outside = wheel(500, 500, 1);
        assertSame(outside, overlay.mouseWheelMoved(outside));
        assertFalse(outside.isConsumed());
        MouseWheelEvent inside = wheel(50, 100, .5);
        overlay.mouseWheelMoved(inside);
        assertTrue(inside.isConsumed());
        BufferedImage after = render(overlay);
        assertFalse(Arrays.equals(((DataBufferInt) before.getRaster().getDataBuffer()).getData(),
            ((DataBufferInt) after.getRaster().getDataBuffer()).getData()));
        assertEquals(new Dimension(280, 360), overlay.getPreferredSize());
        assertTrue(overlay.isResizable());
        state.hide();
        MouseWheelEvent hidden = wheel(50, 100, 1);
        overlay.mouseWheelMoved(hidden);
        assertFalse(hidden.isConsumed());
    }

    private static DeathNotice death(long id)
    {
        return new DeathNotice(id, "Player " + id, "33", "Goblin", 3, "Misthalin", "", null, false);
    }

    private static MouseWheelEvent wheel(int x, int y, double rotation)
    {
        return new MouseWheelEvent(new Canvas(), MouseEvent.MOUSE_WHEEL, 0, 0,
            x, y, x, y, 0, false, MouseWheelEvent.WHEEL_UNIT_SCROLL, 3, (int) rotation, rotation);
    }

    private static BufferedImage render(LastRitesOverlay overlay)
    {
        BufferedImage image = new BufferedImage(300, 380, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try { assertEquals(new Dimension(280, 360), overlay.render(g)); }
        finally { g.dispose(); }
        return image;
    }

    private static final class MutableClock extends Clock
    {
        long now;
        @Override public ZoneId getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(ZoneId zone) { return this; }
        @Override public Instant instant() { return Instant.ofEpochMilli(now); }
        @Override public long millis() { return now; }
    }
}

package com.lastrites;

import java.awt.Component;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.GraphicsEnvironment;
import java.awt.image.BufferedImage;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import javax.imageio.ImageIO;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JSpinner;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assumptions.assumeFalse;
import static org.mockito.Mockito.*;

/** Checks real sidebar controls, including the difference between saved preference and visibility. */
class SidebarControlsTest
{
    @Test
    void sampleChangesVisibilityWithoutCheckingAutomaticPreferenceAndSettingsAreEditable() throws Exception
    {
        assumeFalse(GraphicsEnvironment.isHeadless());
        SwingUtilities.invokeAndWait(() -> {
            AtomicBoolean enabled = new AtomicBoolean(true);
            AtomicBoolean full = new AtomicBoolean(true);
            AtomicInteger seconds = new AtomicInteger(7);
            LastRitesConfig config = mock(LastRitesConfig.class);
            when(config.popupEnabled()).thenAnswer(call -> enabled.get());
            when(config.lookupTotals()).thenAnswer(call -> full.get());
            when(config.duration()).thenAnswer(call -> seconds.get());
            when(config.excludeRegex()).thenReturn("");
            ConfigManager manager = mock(ConfigManager.class);
            doAnswer(call -> {
                switch ((String) call.getArgument(1))
                {
                    case "popupEnabled": enabled.set(call.getArgument(2)); break;
                    case "lookupTotals": full.set(call.getArgument(2)); break;
                    case "duration": seconds.set(call.getArgument(2)); break;
                    default: fail("Unexpected configuration key");
                }
                return null;
            }).when(manager).setConfiguration(eq(LastRitesConfig.GROUP), anyString(), any(Object.class));
            NoticeQueue state = new NoticeQueue();
            LastRitesPanel panel = new LastRitesPanel(state, config, manager,
                () -> {});
            JDialog window = new JDialog();
            try
            {
                window.setContentPane(panel.getWrappedPanel());
                window.setSize(260, 750);
                window.setVisible(true);
                JCheckBox automatic = find(panel, "popupAutomatic", JCheckBox.class);
                automatic.doClick();
                assertFalse(enabled.get());
                find(panel, "popupSample", JButton.class).doClick();
                assertTrue(state.isVisible());
                assertFalse(automatic.isSelected());
                // Run the known Swing timer action, avoiding wall-clock sleeps in UI tests.
                java.lang.reflect.Field timerField = LastRitesPanel.class.getDeclaredField("timer");
                timerField.setAccessible(true);
                Timer timer = (Timer) timerField.get(panel);
                for (java.awt.event.ActionListener listener : timer.getActionListeners()) { listener.actionPerformed(null); }
                assertEquals("Pop-up: visible", find(panel, "popupVisibility", JLabel.class).getText());
                assertEquals("Hide pop-up", find(panel, "popupToggle", JButton.class).getText());
                JSpinner duration = find(panel, "popupDuration", JSpinner.class);
                assertEquals(7, duration.getValue());
                duration.setValue(0);
                assertEquals(0, seconds.get());
                find(panel, "popupFullTotals", JCheckBox.class).doClick();
                assertFalse(full.get());
                assertEquals("To report a bug, open this plugin's Plugin Hub page and use \"Report an issue\".",
                    find(panel, "supportInstructions", javax.swing.JTextArea.class).getText());
                window.validate();
                BufferedImage image = new BufferedImage(260, 750, BufferedImage.TYPE_INT_RGB);
                Graphics2D g = image.createGraphics();
                try { window.getContentPane().printAll(g); }
                finally { g.dispose(); }
                Path output = Path.of("build/previews/sidebar.png");
                Files.createDirectories(output.getParent());
                ImageIO.write(image, "png", output.toFile());
            }
            catch (Exception ex) { throw new AssertionError(ex); }
            finally { panel.stop(); window.dispose(); }
        });
    }

    private static <T extends Component> T find(Container container, String name, Class<T> type)
    {
        for (Component component : container.getComponents())
        {
            if (name.equals(component.getName())) { return type.cast(component); }
            if (component instanceof Container)
            {
                T nested = find((Container) component, name, type);
                if (nested != null) { return nested; }
            }
        }
        return null;
    }
}
